```python
def majority_element(arr):
candidate = None
count = 0

# Phase 1: Find a candidate for majority element
for num in arr:
if count == 0:
candidate = num
count = 1
elif candidate == num:
count += 1
else:
count -= 1

# Phase 2: Verify if the candidate is the majority element
count = 0
for num in arr:
if num == candidate:
count += 1

